# KN7000 "Program" flash image (kn7000_program.rom) - byte-exact.
# Panasonic MN10300, mapped at CPU 0x48400000. GENERATED by
# tools/gen_program_s.py (make program-src) -- do not edit by hand; names
# go in the symbol files, notes in FUNC_DOC or annotations/*.ann. Code
# region 1 and the library image are split at the recovered functions
# (kn7000.sym + kn7000_manual.sym) and emitted as MN10300 assembly, each
# instruction checked byte-exact by the mn10300_asm encoder; their parts
# are in src/program/. The data region is typed source in src/program/data/
# (tools/gen_data_s.py). make verify guarantees byte-identity.
#
# Labels in converted code: a function keeps its symbol-file name (an
# `X_entry` label is the register-save `call` entry a few bytes after the
# `movm` / `add -N, sp` prologue of X); func_<ADDR> is a function no symbol
# file names yet (a call target, a pointer to a prologue, or the code after a
# FUNC_END cap), its call entry func_<ADDR>_entry; loc_<ADDR> a branch
# target or code address inside a function, rodata_<ADDR> typed data. A
# symbol-file name that sits on the call entry itself keeps that address: its
# block header then says where the unlabelled prologue in front of it starts.

.equ PROGRAM_ROM_BASE, 0x48400000
.mnbase 0x48400000   # CPU address of output offset 0 (for PC-relative ops)
.include "src/symbols.inc"
.include "src/program/data/gui_event_ids.inc"   # EV_ / MT_ ids, named in mov / cmp immediates

# 2 names converted code references outside itself (not in symbols.inc)
.equ TableRomDirectory, 0x48000000
.equ LibRomImageBase, 0x487B8FD1

# 11 data addresses named by annotations/*.ann
.equ DrawIcons_PixelPairTable, 0x485A22B8   # 256 x u16: icon byte -> {left, right} palette index (nibble n -> n, or 0xF0+n if n >= 8)
.equ Pixel4bppPairTable, 0x485A24B8   # u16[256]: byte -> two pixels {lo: 0x20 + high nibble, hi: 0x20 + low nibble}
.equ BmpSignature, 0x485A28B8   # "BM", NUL-terminated: the BMP bfType GetBitmapInfo compares
.equ RoundCornerPixels, 0x485A28BC   # 8 x {u16 dx, u16 dy}: the pixels a DrawJpegFileR corner keeps
.equ SjisMissingGlyph, 0x485A28DC   # 16x16 1 bpp column-major glyph: a box with an X in it
.equ DrawEnable, 0x5002A01C   # nonzero: drawing allowed (tested before every DrawXxx_Impl)
.equ FrameBuffer, 0x500D4080   # 640 x 240 x 8 bpp, stride 0x280
.equ BitmapTablePtr, 0x50122DAC   # -> bitmap descriptors {s16 w, s16 h, u8 *pixels}
.equ FrameTablePtr, 0x50122DB0   # -> frame-piece descriptors {s16 w, s16 h, u8 *pixels}
.equ IconTablePtr, 0x50122DB4   # -> icon descriptors {s16 w, s16 h, u8 *pixels}
.equ FontTablePtr, 0x50122DB8   # -> 0x14-byte font descriptors

# ---- boot header (0x0..0x80) ----
_reset:
    jmp     ResetEntry
    nop
    nop
    nop
    nop
    nop
_vector_0a:
    jmp     func_484D77CF
_rom_marker:
    .byte 0x16                              # ROM-present marker (cmp vs 0xFF)
    .space 0x80 - 0x10, 0xFF
    .org 0x000080

# ============================================================================
# Code region 1 -- organised by recovered function.
# ============================================================================
.include "src/program/region1_00.s"
.include "src/program/region1_01.s"
.include "src/program/region1_02.s"
.include "src/program/region1_03.s"
.include "src/program/region1_04.s"
.include "src/program/region1_05.s"
.include "src/program/region1_06.s"
.include "src/program/region1_07.s"
.include "src/program/region1_08.s"
.include "src/program/region1_09.s"
.include "src/program/region1_0A.s"
.include "src/program/region1_0B.s"
.include "src/program/region1_0C.s"
.include "src/program/library_00.s"
.include "src/program/library_01.s"
.mnbase 0x48400000

.org 0x3F6F01   # end of image
